{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:qinghe:knowledge-version:1.0",
  "title": "知识版本基础契约",
  "description": "发布还需服务端验证来源权利、时间关系、审核权限、SKU版本和依赖。Schema合法不代表可以发布。",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "unit_id",
    "version",
    "namespace",
    "tenant_id",
    "knowledge_type",
    "title",
    "body",
    "language",
    "topics",
    "audience_roles",
    "population_scope",
    "excluded_populations",
    "requires",
    "sku_ids",
    "source_refs",
    "status",
    "allowed_tasks",
    "generation_allowed",
    "valid_from",
    "valid_to",
    "review_due",
    "reviewer_ids",
    "limitations",
    "rights",
    "origin",
    "seed_only"
  ],
  "properties": {
    "unit_id": {
      "type": "string",
      "minLength": 1
    },
    "version": {
      "type": "string",
      "pattern": "^\\d+\\.\\d+\\.\\d+$"
    },
    "namespace": {
      "enum": [
        "nutrition_core",
        "qinghe_brand",
        "clinical_reference"
      ]
    },
    "tenant_id": {
      "type": [
        "string",
        "null"
      ],
      "minLength": 1
    },
    "knowledge_type": {
      "enum": [
        "education",
        "product_fact",
        "faq",
        "sop",
        "risk_rule",
        "research_card",
        "communication"
      ]
    },
    "title": {
      "type": "string",
      "minLength": 1
    },
    "body": {
      "type": "string",
      "minLength": 1
    },
    "language": {
      "const": "zh-CN"
    },
    "topics": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "uniqueItems": true
    },
    "audience_roles": {
      "type": "array",
      "minItems": 1,
      "items": {
        "enum": [
          "advisor",
          "supervisor",
          "nutrition_reviewer",
          "compliance_reviewer",
          "content_editor"
        ]
      },
      "uniqueItems": true
    },
    "population_scope": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "uniqueItems": true
    },
    "excluded_populations": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "uniqueItems": true
    },
    "requires": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "uniqueItems": true
    },
    "sku_ids": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "uniqueItems": true
    },
    "source_refs": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": [
          "source_id",
          "locator"
        ],
        "additionalProperties": false,
        "properties": {
          "source_id": {
            "type": "string",
            "minLength": 1
          },
          "locator": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    },
    "status": {
      "enum": [
        "draft",
        "pending_review",
        "approved",
        "published",
        "suspended",
        "retired",
        "superseded"
      ]
    },
    "allowed_tasks": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "minLength": 1
      },
      "uniqueItems": true
    },
    "generation_allowed": {
      "type": "boolean"
    },
    "valid_from": {
      "type": [
        "string",
        "null"
      ],
      "format": "date-time"
    },
    "valid_to": {
      "type": [
        "string",
        "null"
      ],
      "format": "date-time"
    },
    "review_due": {
      "type": [
        "string",
        "null"
      ],
      "format": "date-time"
    },
    "reviewer_ids": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "uniqueItems": true
    },
    "limitations": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "uniqueItems": true
    },
    "rights": {
      "type": "object",
      "required": [
        "status",
        "storage",
        "indexing",
        "generation",
        "external_display"
      ],
      "additionalProperties": false,
      "properties": {
        "status": {
          "enum": [
            "unconfirmed",
            "confirmed",
            "restricted",
            "expired"
          ]
        },
        "storage": {
          "type": "boolean"
        },
        "indexing": {
          "type": "boolean"
        },
        "generation": {
          "type": "boolean"
        },
        "external_display": {
          "type": "boolean"
        }
      }
    },
    "origin": {
      "enum": [
        "internal_policy_draft",
        "public_summary_draft",
        "reviewed_content"
      ]
    },
    "seed_only": {
      "type": "boolean"
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "namespace": {
            "const": "qinghe_brand"
          }
        },
        "required": [
          "namespace"
        ]
      },
      "then": {
        "properties": {
          "tenant_id": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "namespace": {
            "const": "nutrition_core"
          }
        },
        "required": [
          "namespace"
        ]
      },
      "then": {
        "properties": {
          "tenant_id": {
            "type": "null"
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "generation_allowed": {
            "const": true
          }
        },
        "required": [
          "generation_allowed"
        ]
      },
      "then": {
        "properties": {
          "status": {
            "const": "published"
          },
          "seed_only": {
            "const": false
          },
          "reviewer_ids": {
            "minItems": 1
          },
          "valid_from": {
            "type": "string",
            "format": "date-time"
          },
          "review_due": {
            "type": "string",
            "format": "date-time"
          },
          "rights": {
            "properties": {
              "status": {
                "const": "confirmed"
              },
              "storage": {
                "const": true
              },
              "indexing": {
                "const": true
              },
              "generation": {
                "const": true
              }
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "seed_only": {
            "const": true
          }
        },
        "required": [
          "seed_only"
        ]
      },
      "then": {
        "properties": {
          "generation_allowed": {
            "const": false
          },
          "status": {
            "const": "draft"
          }
        }
      }
    }
  ]
}
